/**
 * 니플헤임 지형광 테마 데이터 — 빙원. 등고선을 따라 흐르는 것은 용암이 아니라
 * **크레바스 그림자와 그 가장자리의 서리 림**이다.
 *
 * ## 가산이냐 곱연산이냐 — 실제로 결정할 수 있는 것과 없는 것
 * 겹별 합성 모드는 메커니즘 상수다(`TERRAIN_LIGHT_LAYERS`: dusk·shadow·ao 는 곱연산,
 * glow·core·rim·plume 은 가산). 테마가 정하는 것은 **어느 겹을 켜고 예산을 어디에 두는가**다.
 * 그래서 이 행성의 결정은 셋이다:
 *
 *  1. **예산을 곱연산 쪽으로 옮겼다.** 곱연산의 화면차는 `바닥밝기 × α × (1−배수)` 라
 *     **밝은 바닥에서 잘 듣는다** — 카르곤 암부(합 90)에서 안 듣던 것과 정확히 반대다.
 *     설면(합 285) 위에서 `ao` 0.62 · `shadow` 0.50 은 카르곤과 같은 알파로 3배의 화면차를 낸다.
 *  2. **가산 3종(glow·core·rim)의 색을 전부 저휘도 고채도 청색으로 잡았다.** 가산은 바닥과
 *     무관하게 `α × L` 을 더하므로 밝은 바닥에서는 곧 화이트아웃이자 위장이다. 이 행성 적은
 *     창백한 얼음 시안(L 181~201)이라, 배경을 그 근처로 올리면 적이 사라진다. 실증:
 *     `rim` 0.42 × L 132 = +55 → 설면 90 위에서 145 로, 적 181 아래에 머문다.
 *  3. **`plume`(세 번째 넓은 가산 겹)을 뺐다.** 열기 기둥의 자리인데, 넓은 가산은 위 2번의
 *     위험을 가장 크게 지는 형태다. 눈발·설연은 대기 레이어가 이미 소유하므로 중복이기도 하다.
 *     이 행성에서 "화면 전체"를 담당하는 것은 가산 안개가 아니라 곱연산 `dusk` 다.
 *
 * ## 색상각
 * 얼음의 자연 시안(≈195°)은 **아군 신호색 194.2° 와 사실상 같은 각도**라 쓸 수 없다.
 * 팔레트 전체를 안전 골짜기 204.2°~260.2° 의 깊은 청보라(215°~234°)로 옮겼다.
 *
 * ⚠️ 광원 방향은 여기 없다 — `EnvTheme.light` 가 정본이고 데칼 레이어와 공유한다.
 */

import type { TerrainLightTheme } from '../../contracts/terrainLight.js';

export const NIFLHEIM_TERRAIN_LIGHT: TerrainLightTheme = {
  themeId: 'niflheim',

  /**
   * 크레바스 굴절광 4종. 두꺼운 얼음은 붉은 파장을 먼저 먹어 깊을수록 청색만 남는다 —
   * 그 물리가 팔레트를 안전 골짜기 안쪽(215.0°~233.5°)으로 자연스럽게 밀어 준다.
   * 헤일로는 더 어둡고 채도가 높으며, 심지만 밝다.
   */
  channel: [
    { glow: 0x1e4bd2, core: 0x3a72ee },
    { glow: 0x2a3ec4, core: 0x4a68e6 },
    { glow: 0x1848c0, core: 0x2f7ce8 },
    { glow: 0x3345d8, core: 0x5570f0 },
  ],

  /**
   * **이 행성에서 화면 전체를 담당하는 겹.** 설면이 밝아 곱연산이 그대로 듣는다 —
   * 알파 0.34 × 틴트 휘도 0.272 로 지형이 ×0.75 가 되어, 창백한 적(L 181~201)이 배경보다
   * 확실히 밝게 남는다. 틴트가 청회색이라 눌리는 동시에 푸른 그늘로 읽힌다.
   */
  dusk: { alpha: 0.34, tint: 0x3c4658 },

  glow: { alphaCap: 0.36, width: 96, profileExp: 2.0 },
  /** 심지는 크레바스 바닥의 얼음 굴절광. 좁고(15) 날카롭게(5.6) 두어 면적 대신 첨두만 준다. */
  core: { alphaCap: 0.66, width: 15, profileExp: 5.6 },

  /**
   * 접지 AO — 크레바스 입술 안쪽의 접지 어둠. 폭 14 는 카르곤(16)보다 좁다: 밝은 바닥에서
   * 같은 알파가 3배의 화면차를 내므로 같은 세기를 더 좁은 띠로 얻을 수 있다.
   */
  ao: {
    alphaCap: 0.62,
    tint: 0x3e4a60,
    width: 14,
    offset: 13,
    plateau: 0.5,
    falloffExp: 2.6,
    floor: 0.6,
  },

  /** 저각 태양이 만드는 긴 캐스트 섀도. 틴트가 AO 보다 옅다(캐스트는 접지 어둠보다 밝다). */
  shadow: { alphaCap: 0.5, tint: 0x4c5a72, width: 48, offset: 32, minStrength: 0.12 },

  /**
   * 서리 림 — 크레바스 가장자리에 바람이 얼려 붙인 얇은 서릿발. 이 레이어에서 유일하게
   * 또렷하게 밝은 것이라 색을 창 안에서 **가장 저채도**(=가장 "눈에 가까운")로 잡되,
   * 휘도는 132 로 묶었다(위 2번 산술).
   */
  rim: { alphaCap: 0.42, color: 0x5e86e0, width: 11, widthFloor: 0.5, offset: -15, minStrength: 0.18 },

  /**
   * `plume` 없음 — 위 헤더 3번 참조.
   *
   * 지역 필드 8타일(=512px)은 1920×1080(≈30×17타일) 화면 안에 활성 크레바스 지대가 서너 개
   * 들어가는 크기다. `emberMin` 0.30 은 "닫혀 가는 오래된 크레바스"로 읽히는 대역이고,
   * 여기서 헤일로 실효 알파 ≈0.108 · 심지 ≈0.198 — 붕괴 하한 0.08 위에 있다.
   */
  intensity: {
    regionTiles: 8,
    regionThreshold: 0.55,
    regionSpan: 0.15,
    emberMin: 0.3,
    emberMax: 0.54,
    emberModTiles: 3.4,
    emberRemapLo: 0.32,
    emberRemapHi: 0.68,
    widthBase: 0.55,
    widthGain: 0.45,
  },
};
